def transform(grid):
    h, w = len(grid), len(grid[0])
    marks = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                marks[r + c] = value
    period = next(p for p in range(1, h + w + 1) if all(
        s % p != t % p or a == b
        for s, a in marks.items() for t, b in marks.items()))
    palette = {s % period: value for s, value in marks.items()}
    for x in range(period):
        if x not in palette:
            near = min(palette, key=lambda q: (min((x-q) % period, (q-x) % period), q))
            palette[x] = palette[near]
    out = [[palette[(r + c) % period] for c in range(w)] for r in range(h)]
    assert len(out) == h and all(len(row) == w for row in out)
    assert all(0 <= value <= 9 for row in out for value in row)
    return out

