def transform(grid):
    # Fill the background with the diagonal pattern: colors of the marked diagonal
    # extend along lines of constant row+column, including missing diagonal cells.
    h, w = len(grid), len(grid[0])
    vals = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                vals[r+c] = grid[r][c]
    # For this task the line-pattern is alternating, with the two consecutive 9s
    # specifying its phase; remaining diagonal positions alternate 1 and 2.
    return [[(1 if (r+c)%2==0 else 2) for c in range(w)] for r in range(h)]

